<div class="page-head"><h1>Review: <?= e($assignment['title']) ?></h1><?php $course=course_by_id((int)$assignment['course_id']); ?><p><a href="<?= e(url('/admin/assignments/'.$course['slug'])) ?>">Assignments</a> · <a href="<?= e(url('/admin/gradebook/'.$course['slug'])) ?>">Gradebook</a></p></div>
<?php if (!$submissions): ?><div class="card"><p>No submissions awaiting review.</p></div><?php endif; ?>
<?php foreach ($submissions as $sub): $prefix='s-'.$sub['id']; $criteria=json_decode($assignment['rubric']?:'[]',true); $saved=json_decode($sub['rubric_scores']?:'[]',true); $due=assignment_due($assignment,(int)$sub['user_id']); ?>
<section class="card"><h2><?= e(trim($sub['first_name'].' '.$sub['last_name']) ?: $sub['email']) ?></h2><p><?= e($sub['email']) ?> · <?= e($sub['status']) ?> · Submitted: <?= e($sub['submitted_at']) ?> UTC<?= $due && $sub['submitted_at']>$due?' · Late':'' ?></p><p style="white-space:pre-wrap"><?= e($sub['body']) ?></p><?php if ($sub['file_path']): ?><p><a href="<?= e(url('/assignment-file/'.$sub['id'])) ?>">Download attachment: <?= e($sub['file_name']) ?></a></p><?php endif; ?>
<form method="post" action="<?= e(url('/admin/assignment/'.$assignment['id'].'/'.$sub['user_id'])) ?>"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= (int)$sub['revision'] ?>">
<?php if ($criteria): foreach ($criteria as $i=>$c): ?><div class="field"><label for="<?= e($prefix.'-'.$i) ?>"><?= e($c['title']) ?> (0–<?= e(gb_num($c['max'])) ?>)</label><input id="<?= e($prefix.'-'.$i) ?>" name="rubric_scores[<?= (int)$i ?>]" type="number" min="0" max="<?= e($c['max']) ?>" step="0.01" value="<?= e($saved[$i]['points']??'') ?>" required></div><?php endforeach; else: $score=db_one('SELECT points FROM assessment_scores WHERE assessment_id=? AND user_id=?',[$assignment['id'],$sub['user_id']]); ?><div class="field"><label for="<?= e($prefix) ?>-points">Points (0–<?= e(gb_num($assignment['max_points'])) ?>)</label><input id="<?= e($prefix) ?>-points" name="points" type="number" min="0" max="<?= e($assignment['max_points']) ?>" step="0.01" value="<?= e($score['points']??'') ?>" required></div><?php endif; ?>
<div class="field"><label for="<?= e($prefix) ?>-feedback">Feedback</label><textarea id="<?= e($prefix) ?>-feedback" name="feedback" rows="4" maxlength="50000" style="width:100%"><?= e($sub['feedback']??'') ?></textarea></div><button class="btn btn-gold" type="submit">Save grade and feedback</button></form></section><?php endforeach; ?>
